import { TreeRoot } from "@/components/bevelui/tree";
import type { TreeNodeType } from "@/components/bevelui/tree";
import { IconFolder, IconFile } from "@tabler/icons-react";

const nodes: TreeNodeType[] = [
  {
    id:       "src",
    label:    "src",
    icon:     IconFolder,
    defaultExpanded: true,
    children: [
      {
        id:       "components",
        label:    "components",
        icon:     IconFolder,
        children: [
          { id: "button", label: "button.tsx", icon: IconFile },
          { id: "input",  label: "input.tsx",  icon: IconFile },
        ],
      },
    ],
  },
];

<TreeRoot
  nodes={nodes}
  config={{ multiSelect: true, showLines: true }}
  onSelect={(ids) => console.log("selected:", ids)}
  className="w-56 p-2 rounded-xl border border-border bg-card"
/>

import { useTree } from "@/components/bevelui/tree";

function TreeToolbar() {
  const { expandAll, collapseAll, expandTo, selected } = useTree();

  return (
    <div className="flex gap-2">
      <button onClick={expandAll}>Expand all</button>
      <button onClick={collapseAll}>Collapse all</button>
      <button onClick={() => expandTo("deeply/nested/node")}>Reveal node</button>
      <span>{selected.size} selected</span>
    </div>
  );
}
